1	import { createHmac } from "node:crypto";
2	import { Prisma } from "@prisma/client";
3	import { db } from "@/lib/db";
4	
5	// ── Social rewards: the neutral core ──────────────────────────────────────
6	//
7	// Free credits are REAL model spend on the company card (see lib/credits.ts —
8	// one credit is a fixed $0.002 of underlying spend, so the full 200-credit
9	// sweep is ~$0.40 given away per account). That single fact sets the bar for
10	// everything in this directory: a claim has to be *earned*, and a grant has to
11	// be impossible to repeat.
12	//
13	// This module holds only what both claim paths share — config, identity
14	// hashing, the abuse gates, and the one function that actually writes a grant.
15	// The two paths themselves are deliberately kept apart:
16	//
17	//   ./discord/**  — VERIFIED. Discord's OAuth2 tells us, first-party, whether
18	//                   the authorizing user is in our guild. A real check.
19	//   ./social/**   — UNVERIFIED. Instagram / Facebook / LinkedIn expose no way
20	//                   to ask "does this user follow us". That path is a weaker,
21	//                   self-declared flow and says so, loudly, in its own file.
22	//
23	// Do not blur those two together. The difference is the whole point.
24	
25	/** Credits per platform. 4 platforms x 50 = 200 total, once per account ever. */
26	export const REWARD_CREDITS = 50;
27	
28	export const PLATFORMS = ["discord", "instagram", "facebook", "linkedin"] as const;
29	export type Platform = (typeof PLATFORMS)[number];
30	
31	export const PLATFORM_LABELS: Record<Platform, string> = {
32	  discord: "Discord",
33	  instagram: "Instagram",
34	  facebook: "Facebook",
35	  linkedin: "LinkedIn",
36	};
37	
38	// ── Ledger reason strings are the idempotency key ─────────────────────────
39	//
40	// We cannot add a table (the schema is owned elsewhere), and CreditLedger is
41	// append-only with a free-text `reason`. So `reason` carries the whole state
42	// machine. Two shapes, and only two:
43	//
44	//   reward:<platform>:<identityHash>           delta = +50   a granted reward
45	//   reward:<platform>:pending:<identityHash>   delta =   0   an unverified claim, on hold
46	//
47	// A delta-0 row is a genuine no-op for money: getBalance() reads the newest
48	// row's balanceAfter, and balanceAfter = balance + 0 preserves it exactly;
49	// spentInWindow() only sums delta < 0. So the ledger stays arithmetically
50	// honest while doubling as the only durable store this feature is allowed.
51	//
52	// identityHash is what makes ONE grant per EXTERNAL account, not per Kodely
53	// account — otherwise one Discord login farms fifty signups for 50 credits
54	// each. Because the hash is in the reason string, "has this external identity
55	// ever been rewarded?" is a single indexed-ish scan across ALL users.
56	
57	const REASON_PREFIX = "reward:";
58	
59	export function grantReason(platform: Platform, identityHash: string): string {
60	  return `${REASON_PREFIX}${platform}:${identityHash}`;
61	}
62	
63	export function pendingReason(platform: Platform, identityHash: string): string {
64	  return `${REASON_PREFIX}${platform}:pending:${identityHash}`;
65	}
66	
67	// ── Config ────────────────────────────────────────────────────────────────
68	// Every value is read from process.env at call time. Nothing here is ever
69	// hardcoded, logged, or returned to the browser.
70	
71	/**
