73	 * SHA-256) matters more than it looks. Discord snowflakes and Instagram
74	 * handles are low-entropy and enumerable: an unkeyed digest in a `reason`
75	 * column would let anyone with read access to the ledger confirm "is
76	 * @someuser one of your customers?" by brute force. HMAC with a secret they
77	 * do not have removes that entirely.
78	 *
79	 * There is no fallback. Without the key we cannot enforce one-grant-per-
80	 * identity, and one-grant-per-identity is the only thing standing between
81	 * this feature and a credit farm — so with the key absent we grant nothing.
82	 */
83	export function identitySecret(): string | null {
84	  const secret = process.env.KODELY_REWARDS_ID_SALT;
85	  if (!secret || secret.length < 16) return null;
86	  return secret;
87	}
