147	// ── Abuse gates ───────────────────────────────────────────────────────────
148	
149	/**
150	 * A brand-new account cannot claim. The farm pattern this feature invites is
151	 * "sign up, claim 200, abandon, repeat", and every step of it is cheap except
152	 * waiting. A day of latency costs a real user nothing (they keep their 750
153	 * signup credits meanwhile) and costs a script the only thing it cannot batch.
154	 */
155	export const MIN_ACCOUNT_AGE_HOURS = 24;
156	
157	/**
158	 * Velocity is the signal that actually matters here. Per-user velocity is
159	 * already bounded — four rewards, ever — so the meaningful measurement is
160	 * GLOBAL: a legitimate day sees a trickle of reward grants, while a farm
161	 * being run against us shows up as a burst. Above the ceiling we stop
162	 * granting entirely and shout in the logs, rather than quietly bleeding
163	 * credits until someone reads a dashboard.
164	 *
165	 * Deliberately a circuit breaker, not a queue: claims are not lost, the user
166	 * is told to come back, and a human gets to look first.
167	 */
168	export const VELOCITY_WINDOW_MINUTES = 60;
169	export const VELOCITY_LIMIT = 25;
170	
171	export type Denial =
172	  | "not_configured"
173	  | "account_too_new"
174	  | "already_claimed"
175	  | "identity_already_used"
176	  | "velocity_tripped";
177	
178	export function accountTooNew(userCreatedAt: Date): boolean {
179	  return Date.now() - userCreatedAt.getTime() < MIN_ACCOUNT_AGE_HOURS * 3_600_000;
180	}
181	
182	async function velocityTripped(tx: Prisma.TransactionClient | typeof db): Promise<boolean> {
183	  const since = new Date(Date.now() - VELOCITY_WINDOW_MINUTES * 60_000);
184	  const recent = await tx.creditLedger.count({
185	    where: { reason: { startsWith: REASON_PREFIX }, delta: { gt: 0 }, createdAt: { gte: since } },
186	  });
187	  return recent >= VELOCITY_LIMIT;
188	}
