221	// ── Granting ──────────────────────────────────────────────────────────────
222	
223	/**
224	 * Serialize claims that could collide, using Postgres advisory locks.
225	 *
226	 * Both uniqueness rules here are read-then-write, and CreditLedger has no
227	 * unique constraint on `reason` for us to lean on (we cannot touch the
228	 * schema). Under a double-submitted form or two browser tabs, two requests
229	 * can both read "not yet granted" and both insert — a real double-spend of
230	 * real money. A transaction alone does not fix it: Postgres defaults to READ
231	 * COMMITTED, so the re-read inside the transaction still will not see the
232	 * uncommitted sibling.
233	 *
234	 * Advisory locks do fix it, need no migration, and are released automatically
235	 * when the transaction ends (including on error). Both are taken in a fixed
236	 * order — user first, then identity — so two interleaved claims can never
237	 * deadlock against each other.
238	 *
239	 * $executeRaw, NOT $queryRaw, and that is not a slip. pg_advisory_xact_lock
240	 * returns `void`; $queryRaw tries to deserialize that column and throws
241	 * "Failed to deserialize column of type 'void'". $executeRaw discards rows
242	 * and returns a count, which is all we want. Verified against this app's own
243	 * Postgres: the lock is taken, is re-entrant within the transaction, and is
244	 * released when the transaction ends.
245	 */
246	const LOCK_NAMESPACE = 0x4b4f_4445 | 0; // "KODE"
247	
248	function lockKey(input: string): number {
249	  const secret = identitySecret() ?? "unkeyed";
250	  return createHmac("sha256", secret).update(input).digest().readInt32BE(0);
251	}
252	
253	/**
254	 * Write a grant, or explain why not. The ONLY place in this feature that
255	 * increases a balance.
256	 *
257	 * Mirrors lib/credits.ts `grantCredits` deliberately rather than calling it:
258	 * that helper binds to the global client, and the whole point of this
259	 * function is that the balance read and the ledger insert happen inside the
260	 * same locked transaction. Same row shape, same balanceAfter arithmetic.
261	 */
262	export async function grantReward(
263	  userId: string,
264	  platform: Platform,
265	  hash: string,
266	): Promise<{ ok: true; credits: number } | { ok: false; reason: Denial }> {
267	  if (identitySecret() === null) return { ok: false, reason: "not_configured" };
268	
269	  const userLock = lockKey(`user:${userId}`);
270	  const identityLock = lockKey(`identity:${platform}:${hash}`);
271	
272	  return db.$transaction(async (tx) => {
273	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${userLock}::int4)`;
274	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${identityLock}::int4)`;
275	
276	    const mine = await tx.creditLedger.findFirst({
277	      where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:` }, delta: { gt: 0 } },
278	      select: { id: true },
279	    });
280	    if (mine) return { ok: false as const, reason: "already_claimed" as const };
281	
282	    if (await identityAlreadyUsed(platform, hash, tx)) {
283	      return { ok: false as const, reason: "identity_already_used" as const };
284	    }
285	
286	    if (await velocityTripped(tx)) {
287	      console.error(
288	        `[rewards] velocity ceiling hit (>=${VELOCITY_LIMIT} grants in ${VELOCITY_WINDOW_MINUTES}m) — refusing ${platform} grant. Investigate before raising this.`,
289	      );
290	      return { ok: false as const, reason: "velocity_tripped" as const };
291	    }
292	
293	    const latest = await tx.creditLedger.findFirst({
294	      where: { userId },
295	      orderBy: { createdAt: "desc" },
296	      select: { balanceAfter: true },
297	    });
298	    const balance = latest?.balanceAfter ?? 0;
299	
300	    await tx.creditLedger.create({
301	      data: {
302	        userId,
303	        delta: REWARD_CREDITS,
304	        reason: grantReason(platform, hash),
305	        balanceAfter: balance + REWARD_CREDITS,
306	      },
307	    });
308	
309	    return { ok: true as const, credits: REWARD_CREDITS };
310	  });
311	}
312	
313	/**
314	 * Record an unverified claim as a delta-0 ledger row. Grants nothing.
315	 *
316	 * The zero delta is load-bearing and slightly delicate: getBalance() reads the
317	 * NEWEST row's balanceAfter, so this row has to carry the balance forward
318	 * exactly or it would silently rewrite someone's balance. Hence the same
319	 * locked read-then-insert as grantReward rather than a bare create with a
320	 * balance read from outside the transaction.
321	 *
322	 * (A build charge committing between this transaction's read and its insert
323	 * would still be clobbered — that race is inherent to the ledger's
324	 * read-then-write shape and predates this feature; see chargeForBuild and
325	 * grantCredits in lib/credits.ts, which have it too. The lock at least stops
326	 * rewards racing rewards, which is the part this feature introduced.)
327	 */
328	export async function recordPending(
329	  userId: string,
330	  platform: Platform,
331	  hash: string,
332	): Promise<{ ok: true } | { ok: false; reason: Denial }> {
333	  const userLock = lockKey(`user:${userId}`);
334	  const identityLock = lockKey(`identity:${platform}:${hash}`);
335	
336	  return db.$transaction(async (tx) => {
337	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${userLock}::int4)`;
338	    await tx.$executeRaw`SELECT pg_advisory_xact_lock(${LOCK_NAMESPACE}::int4, ${identityLock}::int4)`;
339	
340	    // Anything at all for this user+platform — granted or already pending —
341	    // means we are done. Re-declaring would otherwise restart the hold clock
342	    // and let someone shop for a handle that passes.
343	    const existing = await tx.creditLedger.findFirst({
344	      where: { userId, reason: { startsWith: `${REASON_PREFIX}${platform}:` } },
345	      select: { id: true },
346	    });
347	    if (existing) return { ok: false as const, reason: "already_claimed" as const };
348	
349	    // Re-checked INSIDE the lock, not just at the route. Two accounts
350	    // declaring the same handle at the same moment would both pass an
351	    // unlocked check, and the loser would only find out 72 hours later when
352	    // their claim was refused.
353	    const taken = await tx.creditLedger.findFirst({
354	      where: {
355	        reason: { in: [grantReason(platform, hash), pendingReason(platform, hash)] },
356	      },
357	      select: { id: true },
358	    });
359	    if (taken) return { ok: false as const, reason: "identity_already_used" as const };
360	
361	    const latest = await tx.creditLedger.findFirst({
362	      where: { userId },
363	      orderBy: { createdAt: "desc" },
364	      select: { balanceAfter: true },
365	    });
366	
367	    await tx.creditLedger.create({
368	      data: {
369	        userId,
370	        delta: 0,
371	        reason: pendingReason(platform, hash),
372	        balanceAfter: latest?.balanceAfter ?? 0,
373	      },
374	    });
375	
376	    return { ok: true as const };
377	  });
378	}
